/* ---------- 品牌头 ---------- */
.brand { padding: 2px 6px; }
.brand h1 { margin: 0; font-size: 16px; letter-spacing: .14em; color: var(--accent); }
.brand h1::before { content: "● "; font-size: 10px; vertical-align: 2px; }
.brand-sub { margin: 2px 0 0; color: var(--dim); font-size: 11.5px; }

/* ---------- 面板通用 ---------- */
.rail, .view, .tablepane, .inspector, .lensbar, .foot {
  background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius);
}

/* ---------- lens_bar ---------- */
.lensbar {
  display: flex; align-items: center; flex-wrap: wrap; gap: 6px;
  padding: 6px 8px; min-height: 40px;
}
.count-pill {
  font-family: var(--mono); font-size: 12px; color: var(--accent);
  border: 1px solid var(--line); border-radius: 999px; padding: 3px 10px;
  background: var(--panel-2); white-space: nowrap;
}
.count-pill.is-filtered { color: var(--sel); border-color: #4a4426; }
.chips { display: flex; flex-wrap: wrap; gap: 4px; align-items: center; }
.chips-proj { border-left: 1px solid var(--line); padding-left: 6px; }
.chip {
  display: inline-flex; align-items: center; gap: 5px;
  border: 1px solid var(--line); background: var(--panel-2);
  border-radius: 999px; padding: 2.5px 4px 2.5px 8px; font-size: 12px;
}
.chip-owner {
  font-size: 10px; color: var(--accent-ink); background: var(--accent);
  border-radius: 999px; padding: 0.5px 6px; font-weight: 600; white-space: nowrap;
}
.chip-proj .chip-owner { background: #2d3b4a; color: var(--dim); }
.chip-default { opacity: .62; }
.chip-label { white-space: nowrap; }
.chip-x {
  border: 0; background: transparent; color: var(--dim); cursor: pointer;
  width: 18px; height: 18px; border-radius: 50%; font-size: 13px; line-height: 1;
}
.chip-x:hover { background: var(--danger); color: #fff; }
.chip-x.is-disabled { cursor: default; }
.chip-x.is-disabled:hover { background: transparent; color: var(--dim); }
.chip-empty { color: var(--dim); font-style: italic; padding: 2.5px 10px; }

.lens-actions { margin-left: auto; display: flex; gap: 5px; }
.btn {
  border: 1px solid var(--line); background: var(--panel-2); color: var(--text);
  border-radius: var(--radius); padding: 4px 10px; font-size: 12px; cursor: pointer;
  display: inline-flex; align-items: center; gap: 5px;
}
.btn:hover:not(:disabled) { border-color: var(--accent); color: var(--accent); }
.btn:disabled { opacity: .45; cursor: default; }
.btn-quiet { opacity: .55; }
.btn-accent { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); font-weight: 600; }
.btn-accent:hover { color: var(--accent-ink); filter: brightness(1.08); }
.btn-badge {
  font-family: var(--mono); font-size: 10px; background: #2d3b4a;
  border-radius: 999px; padding: 0 5px; color: var(--dim);
}

/* 过滤构建器（内联，不弹模态） */
.builder {
  flex-basis: 100%; border-top: 1px dashed var(--line);
  padding-top: 6px; display: flex; flex-wrap: wrap; gap: 8px; align-items: flex-start;
}
.fld { display: flex; align-items: center; gap: 6px; }
.fld-k { color: var(--dim); font-size: 11.5px; }
.fld-row .inp { width: 90px; }
.fld-sep { color: var(--dim); }
.sel, .inp {
  background: var(--panel-2); color: var(--text); border: 1px solid var(--line);
  border-radius: var(--radius); padding: 4px 8px; font-size: 12px;
}
.sel:focus-visible, .inp:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
.valgrid { display: flex; flex-wrap: wrap; gap: 4px; }
.val {
  display: inline-flex; align-items: center; gap: 5px;
  background: var(--panel-2); border: 1px solid var(--line); color: var(--text);
  border-radius: 999px; padding: 3px 10px; font-size: 12px; cursor: pointer;
}
.val.is-on { border-width: 2px; padding: 2px 9px; background: #1a2530; }
.sw { width: 9px; height: 9px; border-radius: 2px; display: inline-block; }
.sw-big { width: 14px; height: 14px; border-radius: 3px; display: inline-block; }
.builder-actions { display: flex; gap: 5px; }

/* ---------- dimension_rail ---------- */
.rail { overflow-y: auto; padding: 8px; }
.rail-sec { margin-bottom: 10px; }
.rail-h {
  margin: 2px 0 5px; font-size: 10.5px; letter-spacing: .12em;
  color: var(--dim); text-transform: uppercase; font-weight: 600;
}
.dim {
  display: flex; align-items: baseline; gap: 7px; width: 100%; text-align: left;
  background: transparent; border: 1px solid transparent; border-radius: var(--radius);
  color: var(--text); padding: 4px 7px; font-size: 12.5px; cursor: pointer;
}
.dim:hover { background: var(--panel-2); border-color: var(--line); }
.dim.is-active { background: #10314a; border-color: var(--accent); }
.dim.is-active .dim-label { color: var(--accent); font-weight: 600; }
.dim-type { color: var(--dim); font-size: 10px; width: 12px; }
.dim-label { flex: 1; }
.dim-meta { color: var(--dim); font-size: 10.5px; font-family: var(--mono); }
.rail-sum { border-top: 1px solid var(--line); padding-top: 6px; }
.sum-row { display: flex; gap: 8px; font-size: 11.5px; padding: 1.5px 2px; }
.sum-row span { color: var(--dim); width: 30px; }
.sum-row b { font-weight: 600; }

/* ---------- projection_view ---------- */
.view { display: flex; flex-direction: column; min-width: 0; overflow: hidden; }
.view-head {
  display: flex; align-items: center; gap: 12px; flex-wrap: wrap;
  padding: 7px 10px 0;
}
.view-mode { color: var(--dim); font-size: 12px; font-weight: 600; }
.legend { display: flex; flex-wrap: wrap; gap: 4px; margin-left: auto; }
.lg {
  display: inline-flex; align-items: center; gap: 5px; font-size: 11.5px;
  background: transparent; border: 1px solid var(--line); border-radius: 999px;
  color: var(--text); padding: 2px 9px; cursor: pointer;
}
.lg:hover { border-color: var(--accent); }
.lg.is-off { opacity: .38; text-decoration: line-through; }
.view-body { flex: 1; display: flex; align-items: center; justify-content: center; padding: 2px 6px 6px; min-height: 0; }
.chart { width: 100%; height: 100%; max-height: 100%; }
.gridline { stroke: #1d2733; stroke-width: 1; }
.axisline { stroke: #33465a; }
.tick { fill: var(--dim); font-size: 10.5px; font-family: var(--mono); }
.tick-sel { fill: var(--sel); font-weight: 700; }
.axname { fill: var(--dim); font-size: 11px; }
.hit { fill: transparent; cursor: pointer; }
.hit:hover { fill: rgba(88, 196, 255, .07); }
.hit:focus-visible { outline: 2px solid var(--accent); }
.seg { pointer-events: none; }
.pt { cursor: pointer; }
.pt:hover { stroke: #fff; stroke-width: 1; }
.pt.is-sel { stroke: var(--sel); stroke-width: 2; }
.sel-ring { fill: none; stroke: var(--sel); stroke-width: 1.5; opacity: .9; }
.guide { stroke: var(--sel); stroke-width: 1; stroke-dasharray: 3 3; opacity: .65; }
.sel-band { fill: rgba(255, 209, 102, .12); stroke: var(--sel); stroke-width: 1.2; }
.view-empty {
  display: flex; flex-direction: column; align-items: center; gap: 10px;
  color: var(--dim); padding: 40px; text-align: center;
}

/* ---------- records_table ---------- */
.tablepane { display: flex; flex-direction: column; min-height: 0; overflow: hidden; }
.table-head { display: flex; align-items: baseline; gap: 10px; padding: 6px 10px 4px; }
.table-head h3 { margin: 0; font-size: 12px; letter-spacing: .08em; color: var(--dim); text-transform: uppercase; }
.table-count { color: var(--dim); font-size: 11px; font-family: var(--mono); }
.table-scroll { overflow-y: auto; flex: 1; }
.tbl { width: 100%; border-collapse: collapse; font-size: 12px; }
.tbl th {
  position: sticky; top: 0; background: var(--panel); color: var(--dim);
  text-align: left; font-weight: 600; font-size: 11px; padding: 3px 10px;
  border-bottom: 1px solid var(--line); white-space: nowrap;
}
.tbl td { padding: 2.5px 10px; border-bottom: 1px solid #1a222c; }
.tbl tbody tr { cursor: pointer; }
.tbl tbody tr:hover { background: var(--panel-2); }
.tbl tbody tr.is-sel { background: #2a2413; box-shadow: inset 3px 0 0 var(--sel); }
.tbl tbody tr.is-sel .rowbtn { color: var(--sel); font-weight: 700; }
.tbl .num { font-family: var(--mono); font-size: 11.5px; color: var(--dim); }
.tbl tbody tr.is-sel .num { color: var(--text); }
.rowbtn {
  background: transparent; border: 0; color: var(--text); cursor: pointer;
  font: inherit; padding: 0; text-align: left;
}
.rowbtn:hover { color: var(--accent); text-decoration: underline; }
.empty-row td { color: var(--dim); text-align: center; padding: 14px; }

/* ---------- inspector ---------- */
.inspector { overflow-y: auto; padding: 10px 12px; }
.insp-empty h3 { margin: 4px 0 6px; font-size: 13px; color: var(--dim); }
.insp-empty p { color: var(--dim); font-size: 12px; }
.insp-id { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin-bottom: 6px; }
.insp-badge {
  font-size: 10px; letter-spacing: .1em; color: var(--sel);
  border: 1px solid #4a4426; border-radius: 999px; padding: 1px 8px;
}
.insp-name { margin: 0; font-size: 15px; font-family: var(--mono); }
.insp-sec { border-top: 1px solid var(--line); padding: 6px 0 2px; }
.insp-h { margin: 0 0 4px; font-size: 10.5px; letter-spacing: .12em; color: var(--dim); text-transform: uppercase; }
.insp-row { display: grid; grid-template-columns: 76px 1fr 74px; gap: 6px; align-items: center; padding: 2px 0; }
.insp-k { color: var(--dim); font-size: 11.5px; }
.insp-val { font-size: 12px; display: inline-flex; align-items: center; gap: 5px; }
.track { position: relative; height: 3px; background: #222d3a; border-radius: 2px; }
.dot {
  position: absolute; top: 50%; width: 7px; height: 7px; border-radius: 50%;
  background: var(--accent); transform: translate(-50%, -50%);
}
.insp-note { color: var(--dim); font-size: 11px; border-top: 1px dashed var(--line); padding-top: 6px; }

/* ---------- status_footer ---------- */
.foot {
  display: flex; gap: 16px; align-items: center; padding: 5px 12px;
  font-size: 11.5px; color: var(--dim); font-family: var(--mono);
}
.foot-last { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.foot-state.is-error { color: var(--danger); }

/* ---------- 键盘焦点（可见焦点 — WCAG 2.2） ---------- */
.btn:focus-visible, .chip-x:focus-visible, .dim:focus-visible, .lg:focus-visible,
.val:focus-visible, .rowbtn:focus-visible {
  outline: 2px solid var(--accent); outline-offset: 1px; border-radius: 4px;
}

/* 滚动条 */
::-webkit-scrollbar { width: 9px; height: 9px; }
::-webkit-scrollbar-thumb { background: #263140; border-radius: 5px; }
::-webkit-scrollbar-track { background: transparent; }

