  }
  function resetAll() {
    var snap = { op: 'restore', lens: state.lens, x: state.x, y: state.y, color: state.color };
    state.lens = [];
    state.x = INITIAL.x; state.y = INITIAL.y; state.color = INITIAL.color;
    pushUndo(snap);
