1	/* EXO·LENS — 系外行星维度探索
2	 * app.js — 状态 store（lens/selection/projection，含撤销栈）+ 区域渲染器
3	 *
4	 * 区域（SDIR dimension_explorer_main）：lens_bar / dimension_rail /
5	 * projection_view（dominant）/ records_table / inspector / status_footer
6	 * 维度切换只重绘 projection_view（及表格取值），其余区域为定向不变量。
7	 */
8	(function () {
9	  'use strict';
10	
11	  var DATA = window.DATA;
12	  var DIMS = DATA.dims;
13	  var RECORDS = DATA.records;
14	  var PALETTE = DATA.palette;
15	
16	  // ---------- 基础工具 ----------
17	  function $(sel, root) { return (root || document).querySelector(sel); }
18	  function dim(id) { for (var i = 0; i < DIMS.length; i++) if (DIMS[i].id === id) return DIMS[i]; return null; }
19	  function catValues(d) { return d.values; }
20	  function catColor(d, v) { return PALETTE[d.values.indexOf(v) % PALETTE.length]; }
21	
22	  function fmtNum(v, d) {
23	    if (typeof v !== 'number' || !isFinite(v)) return String(v);
24	    if (d && d.integer) return String(Math.round(v));
25	    var a = Math.abs(v);
26	    if (a >= 1000) return (v / 1000).toFixed(1).replace(/\.0$/, '') + 'k';
27	    if (a >= 100) return String(Math.round(v));
28	    if (a >= 10) return String(Math.round(v));
29	    if (a >= 1) return v.toFixed(1);
30	    return v.toFixed(2);
31	  }
32	  function shortLabel(d, v) { return (d.short && d.short[v]) ? d.short[v] : v; }
33	  function tOf(d, v) { return (d.scale === 'log') ? Math.log10(Math.max(v, 1e-6)) : v; }
34	  function tInv(d, t) { return (d.scale === 'log') ? Math.pow(10, t) : t; }
