    renderAll();
  }
  function removeFilter(id) {
    var f = null;
    for (var i = 0; i < state.lens.length; i++) if (state.lens[i].id === id) f = state.lens[i];
    if (!f) return;
    state.lens = state.lens.filter(function (x) { return x.id !== id; });
    pushUndo({ op: 'addFilter', entry: f });
