      h('div', { class: 'sum-row' }, h('span', { text: 'Y' }), h('b', { text: axisValueText('y', state.y) })),
      h('div', { class: 'sum-row' }, h('span', { text: '颜色' }), h('b', { text: axisValueText('color', state.color) })));
